-- Written per row: name, name_i18n (9 languages, ISO keys as the app reads them), category 'beach', region, area, latitude, longitude,
-- source, source_id, status. Ministry rows also: description_i18n (9 languages) and, only where the page itself states it,
-- amenities / access_type. NOT written: blue_flag, any photo column, address, phone, website, provider_id, submitted_by.
--
-- status 'staged' (20261178): every row is readable ONLY with the ADA Preview key, so production users see none of it. Publishing is a
-- LATER migration, on Berke's go after he has checked every pin on Preview. ⚠ That migration MUST be scoped
-- `WHERE category = 'beach' AND status = 'staged'`: the 399 staged OSM shop rows of 20261179 share source 'osm' and must not ride along.
-- The 4 LIVE beaches are untouched here, and their extra locales are NOT in this file (data/explore/beaches-live-translations.json holds them
-- for a separate migration). Re-running this file inserts nothing (ON CONFLICT (source, source_id) DO NOTHING) and still passes after a
-- publish: it only requires each of its rows to exist as a beach that is 'staged' or already 'active', and it proves it published nothing.
--
-- Assertions (inside the transaction; they print counts and booleans only, never a row value):
--   a. every one of this file's 30 (source, source_id) pairs exists exactly once, category 'beach', status 'staged' or 'active';
--   b. scope — captured BEFORE the INSERT and compared AFTER, by count and an md5 of the whole rows: places that are not beaches, beaches that
--      are not this file's, and ALL status 'active' rows are identical (so this file published nothing and touched nothing); the table grew by
--      exactly the rows this file added;
--   c. rows of this file that are still 'staged' carry no description / amenities / access_type unless Ministry, and no blue_flag, cover image,
--      photos, photo credits or attribution, provider_id, submitted_by, hidden_at; every one has the 9 name_i18n keys;
--   d. the FULL pg_policies set on places is read (9 expected: 5 permissive, 4 restrictive — migrations 20260822, 20260824, 20261178; the live
--      count was confirmed by the 2026-11-16 probe), and the only policy that mentions 'staged' is places_select_preview_staged (SELECT, with
--      is_previewer()); places_select still has its 'active' arm (positive control); exactly two permissive policies can read rows;
--   e. the enabled INSERT-firing triggers on places are exactly 4, all BEFORE ROW: places_guard_insert (20260825) and places_guard_source
--      (20261045) and places_guard_official_visit (20261155) each return NEW at once when auth.uid() IS NULL, as here (postgres, no session);
--      check_place_content (20260824) re-scans name + name_i18n + description_i18n values with contains_blocked_term() and
--      contains_payment_solicitation() on every INSERT, with no admin or role exemption — a hit RAISES and rolls this whole file back.
--      scripts/test-beaches-staged.mjs runs the real functions over the real text; see that file for what that does and does not prove.
--
-- Apply: gh workflow run supabase-migrate -f file=20261207_beaches_staged.sql (dry), then -f apply=true after Berke approves production-db.
-- Data only: no schema change, nothing to register in verify_schema.sql, no NOTIFY needed.

SET ROLE postgres;

BEGIN;

SET LOCAL lock_timeout = '5s';

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.places'::regclass
                  AND conname = 'places_status_check' AND pg_get_constraintdef(oid) LIKE '%staged%') THEN
    RAISE EXCEPTION 'REFUSING: 20261178 (staged status) is not applied';
  END IF;
END $$;

-- ─── Capture the BEFORE state in transaction-local settings (no temp table, nothing printed) ───
DO $$
DECLARE
  v_pairs jsonb := '[["visitncy_beaches","kervansaray-beach"],["visitncy_beaches","long-beach"],["osm","way/225386412"],["osm","way/608212204"],["osm","way/225382750"],["osm","way/1484271058"],["osm","way/286275732"],["osm","way/603986283"],["osm","way/208150337"],["osm","way/286276160"],["osm","way/208111924"],["osm","way/229043037"],["osm","way/225383964"],["osm","way/244561269"],["osm","node/11994931556"],["osm","way/208241783"],["osm","way/666114116"],["osm","node/11231014679"],["osm","way/435771323"],["osm","relation/15456405"],["osm","way/606238631"],["osm","way/1365670207"],["osm","way/309623318"],["osm","way/1395325670"],["osm","way/952236170"],["osm","relation/13040159"],["osm","node/1951274050"],["osm","way/510986434"],["osm","way/435772839"],["osm","way/603896219"]]'::jsonb;
  v_before jsonb;
BEGIN
  SELECT jsonb_build_object(
    'pairs', v_pairs,
    'total',   (SELECT count(*) FROM public.places),
    'present', (SELECT count(*) FROM public.places p WHERE EXISTS (
                  SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id)),
    'nb_n',  (SELECT count(*) FROM public.places WHERE category IS DISTINCT FROM 'beach'),
    'nb_md5', (SELECT md5(coalesce(string_agg(to_jsonb(p)::text, '|' ORDER BY p.id), '')) FROM public.places p WHERE p.category IS DISTINCT FROM 'beach'),
    'ob_n',  (SELECT count(*) FROM public.places p WHERE p.category IS NOT DISTINCT FROM 'beach' AND NOT EXISTS (
                SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id)),
    'ob_md5', (SELECT md5(coalesce(string_agg(to_jsonb(p)::text, '|' ORDER BY p.id), '')) FROM public.places p WHERE p.category IS NOT DISTINCT FROM 'beach' AND NOT EXISTS (
                SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id)),
    'act_n', (SELECT count(*) FROM public.places WHERE status IS NOT DISTINCT FROM 'active'),
    'act_md5', (SELECT md5(coalesce(string_agg(to_jsonb(p)::text, '|' ORDER BY p.id), '')) FROM public.places p WHERE p.status IS NOT DISTINCT FROM 'active')
  ) INTO v_before;
  PERFORM set_config('ada.beaches_before', v_before::text, true);
END $$;

INSERT INTO public.places (name, name_i18n, description_i18n, category, region, area, latitude, longitude, access_type, amenities, source, source_id, status)
VALUES
  ('Kervansaray Beach', '{"en":"Kervansaray Beach","tr":"Kervansaray Plajı","ar":"شاطئ كرفانسراي","ru":"Пляж Кервансарай","el":"Παραλία Κερβανσαράι","fr":"Plage Kervansaray","es":"Playa Kervansaray","de":"Kervansaray-Strand","fa":"ساحل کروانسرای"}'::jsonb, '{"en":"Operated by the Municipality of Kyrenia, this is a popular public leisure area in the Kervansaray area. It has sunbeds and umbrellas, dressing rooms and showers, restaurants, a car park for the disabled with easy access to the beach, and a swimming area marked off by buoys. There is a lifeguard tower with first aid.","tr":"Girne Belediyesi tarafından işletilen, Kervansaray bölgesinde herkesin yararlanabileceği gözde bir dinlence alanıdır. Şezlong ve şemsiyeler, soyunma kabinleri ve duşlar, restoranlar, plaja kolay erişimi olan bir engelli otoparkı ve şamandıralarla ayrılmış bir yüzme alanı bulunur. Ayrıca ilk yardım olanağı bulunan bir cankurtaran kulesi vardır.","ar":"تديرها بلدية كيرينيا، وهي منطقة ترفيهية شهيرة مفتوحة للجمهور في منطقة كرفانسراي. تتوفر فيها كراسي الاستلقاء والمظلات وغرف تبديل الملابس والاستحمام والمطاعم وموقف سيارات للأشخاص ذوي الإعاقة مع وصول سهل إلى الشاطئ ومنطقة سباحة محددة بالعوامات. ويوجد برج لإنقاذ الغرقى مزوّد بالإسعافات الأولية.","ru":"Пляж находится в ведении муниципалитета Кирении. Это популярная зона отдыха, открытая для всех, в районе Кервансарай. Здесь есть шезлонги и зонты, раздевалки и душевые, рестораны, парковка для людей с ограниченными возможностями с удобным доступом к пляжу и зона для купания, огороженная буями. Есть спасательная вышка с пунктом первой помощи.","el":"Λειτουργεί από τον Δήμο Κερύνειας και είναι ένας δημοφιλής χώρος αναψυχής ανοιχτός στο κοινό, στην περιοχή Κερβανσαράι. Διαθέτει ξαπλώστρες και ομπρέλες, αποδυτήρια και ντους, εστιατόρια, χώρο στάθμευσης για άτομα με αναπηρία με εύκολη πρόσβαση στην παραλία και ζώνη κολύμβησης οριοθετημένη με σημαδούρες. Υπάρχει πύργος ναυαγοσωστών με πρώτες βοήθειες.","fr":"Gérée par la municipalité de Kyrenia, c''est une zone de loisirs populaire, ouverte au public, dans le quartier de Kervansaray. On y trouve des transats et des parasols, des cabines de change et des douches, des restaurants, un parking pour personnes handicapées avec un accès facile à la plage et une zone de baignade délimitée par des bouées. Une tour de surveillance avec premiers secours est présente.","es":"Gestionada por el municipio de Kyrenia, es una popular zona de ocio abierta al público, en la zona de Kervansaray. Cuenta con tumbonas y sombrillas, vestuarios y duchas, restaurantes, un aparcamiento para personas con discapacidad con fácil acceso a la playa y una zona de baño delimitada con boyas. Dispone de una torre de socorrismo con primeros auxilios.","de":"Der Strand wird von der Gemeinde Kyrenia betrieben und ist ein beliebtes Freizeitgelände für die Öffentlichkeit im Gebiet Kervansaray. Es gibt Liegen und Sonnenschirme, Umkleidekabinen und Duschen, Restaurants, einen Parkplatz für Menschen mit Behinderung mit leichtem Zugang zum Strand und einen durch Bojen abgetrennten Badebereich. Ein Rettungsschwimmerturm mit Erster Hilfe ist vorhanden.","fa":"این ساحل را شهرداری کیرنیا اداره می‌کند و منطقه‌ای تفریحی و محبوب برای عموم در محدوده کروانسرای است. در آن تخت‌های آفتابی و چتر، رختکن و دوش، رستوران، پارکینگ ویژه افراد دارای معلولیت با دسترسی آسان به ساحل و محدوده شنای مشخص‌شده با شناور وجود دارد. یک برج نجات‌غریق همراه با کمک‌های اولیه نیز در آن هست."}'::jsonb, 'beach', 'kyrenia', NULL, 35.347758, 33.255979, 'public', ARRAY['sunbeds', 'food_bar', 'lifeguard']::text[], 'visitncy_beaches', 'kervansaray-beach', 'staged'),
  ('Long Beach', '{"en":"Long Beach","tr":"Long Beach","ar":"Long Beach","ru":"Long Beach","el":"Long Beach","fr":"Long Beach","es":"Long Beach","de":"Long Beach","fa":"Long Beach"}'::jsonb, '{"en":"Situated on Salamis Bay, about 15 km north of Famagusta and near the ruins of Salamis, this sandy beach offers a range of facilities. A shuttle service runs from town to the beach.","tr":"Salamis Körfezi''nde, Gazimağusa''nın yaklaşık 15 km kuzeyinde ve Salamis kalıntılarına yakın konumdaki bu kumsal plaj, çeşitli olanaklar sunar. Şehirden plaja bir servis hizmeti de işler.","ar":"يقع على خليج سلاميس، على بعد نحو 15 كم شمال فاماغوستا وبالقرب من آثار سلاميس، وهو شاطئ رملي يوفر مجموعة من المرافق. وتعمل خدمة نقل مكوكية من المدينة إلى الشاطئ.","ru":"Этот песчаный пляж находится в заливе Саламис, примерно в 15 км к северу от Фамагусты, рядом с руинами Саламина, и предлагает ряд удобств. От города до пляжа курсирует трансфер.","el":"Αυτή η αμμώδης παραλία βρίσκεται στον κόλπο της Σαλαμίνας, περίπου 15 χλμ. βόρεια της Αμμοχώστου και κοντά στα ερείπια της Σαλαμίνας, και προσφέρει μια σειρά από παροχές. Δρομολόγιο μεταφοράς εκτελείται από την πόλη προς την παραλία.","fr":"Située sur la baie de Salamine, à environ 15 km au nord de Famagouste et près des ruines de Salamine, cette plage de sable propose un éventail d''équipements. Un service de navette relie la ville à la plage.","es":"Situada en la bahía de Salamina, a unos 15 km al norte de Famagusta y cerca de las ruinas de Salamina, esta playa de arena ofrece una variedad de instalaciones. Hay un servicio de autobús lanzadera desde la ciudad hasta la playa.","de":"Der Sandstrand liegt an der Bucht von Salamis, etwa 15 km nördlich von Famagusta und in der Nähe der Ruinen von Salamis, und bietet eine Reihe von Einrichtungen. Ein Shuttleservice fährt von der Stadt zum Strand.","fa":"این ساحل ماسه‌ای در خلیج سالامیس، حدود 15 کیلومتر شمال فاماگوستا و نزدیک خرابه‌های سالامیس قرار دارد و امکانات متنوعی ارائه می‌دهد. یک سرویس شاتل نیز از شهر به ساحل رفت‌وآمد می‌کند."}'::jsonb, 'beach', 'iskele', 'long-beach', 35.266136, 33.915938, 'public', NULL, 'visitncy_beaches', 'long-beach', 'staged'),
